28:    IN_REWORK: 'In Rework',                         // PR review failed, focused fixes needed
156: *   const statuses = resolveStatuses(customParams, config.jira && config.jira.statuses);
172:function resolveStatuses(customParams, projectStatuses) {
221:    resolveStatuses
349:        var statuses = resolveStatuses(customParams, config.jira && config.jira.statuses);
360:        // (gh-802 AC3b): a rework leg used to write statuses.IN_DEVELOPMENT —
365:        // real transition target: statuses.IN_REWORK.
368:                tracker.moveToStatus(ticketKey, statuses.IN_REWORK);
369:                console.log('Moved ' + ticketKey + ' to ' + statuses.IN_REWORK);
371:                console.warn('Failed to move ticket to ' + statuses.IN_REWORK + ':', e);

        var plan = questionsFetchPlan(provider, questionsConfig, ticketKey);

        if (plan.skip) {
            console.warn('Skipping question subtask fetch — ' + plan.reason);
        } else try {
            var rawQuestions = tracker.searchIssues(plan.jql, {
                fields: ['key', 'summary', 'description', 'status', 'priority', answerField]
            });
            var questions = [];
            for (var i = 0; i < rawQuestions.length; i++) {
                var issue = rawQuestions[i];
                var f = issue.fields || {};
                questions.push({
                    key: issue.key || '',
                    summary: f.summary || '',
                    description: f.description || '',
                    status: f.status ? f.status.name : '',
                    priority: f.priority ? f.priority.name : '',
                    answer: getAnswerValue(f, answerField)
                });
            }
            console.log('Found ' + questions.length + ' question subtasks');
            // Wrap in object: file_write bridge auto-parses strings starting with '[' as ArrayList.
            file_write(folder + '/existing_questions.json', '{"questions":' + JSON.stringify(questions, null, 2) + '}');
            console.log('Wrote existing_questions.json to ' + folder);
        } catch (fetchError) {
            // gh-802 AC3c: the host console renders a raw Error object as "{}"
            // (the cause was invisible in the logs) — log the CONTENT instead.
            var fetchErrorDetail = fetchError && fetchError.message
                ? fetchError.message
                : String(fetchError);
            console.error('Failed to fetch questions, continuing without file:', fetchErrorDetail);
        }
    } catch (error) {
        console.error('Error in fetchQuestionsToInput:', error);
    }

    // Enrich input with parent story + [BA]/[SA]/[VD] context
    try {
        var fetchParentContextToInput = require('./fetchParentContextToInput.js');
        fetchParentContextToInput.action(params);
    } catch (e) {
        console.warn('fetchParentContextToInput failed (non-fatal):', e);
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action, getAnswerValue, hasAnswerValue, questionsFetchPlan };
}

